/// <summary>
///    The <c>UnitOfMeasureLookup</c> class provides the methods to perform lookup on the
///    <c>EcoResProduct</c> table, controls the <c>EcoResProductLookup</c> lookup form behavior, and
///    handles form events.
/// </summary>
class GUPFulfillmentPolicyLookup
{
    public  boolean returnRefRecID = false;

}

Method.Source:
final public boolean parmreturnRefRecID(boolean _returnRefRecID = returnRefRecID)
{
    returnRefRecID = _returnRefRecID;

    return returnRefRecID;
}

public WHSFulfillmentPolicy performLookup(FormStringControl _formStringControl)
{
    Args args = new Args();
    args.name(formStr(GUPFulfillmentPolicyLookup));
    args.caller(this);

    args.parmObject(this);
    args.lookupField(fieldNum(WHSFulfillmentPolicy, RecId));
    args.lookupValue(_formStringControl.valueStr());

    FormRun formRun = classfactory.formRunClass(args);
    formRun.init();

    _formStringControl.performFormLookup(formRun);
    WHSFulfillmentPolicy wHSFulfillmentPolicy = formRun.selectRecordModeSelectedRecord() as WHSFulfillmentPolicy;

    return wHSFulfillmentPolicy;
}

public static GUPFulfillmentPolicyLookup construct(boolean _returnRefRecID)
{
    return new GUPFulfillmentPolicyLookup(_returnRefRecID);
}
